cat > /tmp/verify/verify_main.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const net = [];
    page.on('pageerror', e => net.push('pageerror: ' + e.message));
    page.on('response', async r => { if (r.url().includes('_search')) { let b=''; try { b=(await r.text()).replace(/\s+/g,' ').slice(0,120);} catch(e){} net.push('search ' + r.status() + ' ' + b); } });
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(3000);
    console.log('INDEX_OPTIONS: ' + JSON.stringify(await page.$eval('#chooseIndex', el => Array.from(el.options).map(o=>o.textContent.trim()))));
    // pick the demo index
    await page.selectOption('#chooseIndex', { label: 'index_data_explorer_demo' });
    await page.waitForTimeout(3000);
    // filter field
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(500);
    const fields = await page.$eval('#dataExplorerDataFields', el => Array.from(el.options).map(o=>o.textContent.trim()));
    console.log('DEMO_FIELDS: ' + JSON.stringify(fields));
    await page.selectOption('#dataExplorerDataFields', 'name');
    await page.waitForTimeout(1500);
    // output: bar chart + dimension
    await page.click('.oneCollapsibleItem.output .collapsible-header');
    await page.waitForTimeout(500);
    await (await page.$('#outputControls select.chartTypeChooser, #outputControls select')).selectOption('barChart');
    await page.waitForTimeout(1000);
    const dim = await page.$('#outputControls select.dimension');
    if (dim) await dim.selectOption('name');
    await page.waitForTimeout(500);
    await page.click('#getResults');
    await page.waitForTimeout(9000);
    const svg = await page.$$eval('#graphicsWrapper svg', s => s.length).catch(() => -1);
    const texts = await page.$$eval('#graphicsWrapper svg text', t => t.slice(0,10).map(x=>x.textContent)).catch(()=>[]);
    console.log('SVG_COUNT: ' + svg + ' TEXTS: ' + JSON.stringify(texts));
    console.log('NET: ' + JSON.stringify(net));
    await page.screenshot({ path: '/tmp/verify/main_page.png', fullPage: true });
    await browser.close();
})().catch(e => { console.error('VERIFY_FAILED', e.message); process.exit(1); });
EOF
cd /tmp/verify && node verify_main.js 2>&1 | tail -15

